const trigger = $('Upload Webhook').first().json;
const originalFileName = $binary?.file?.fileName || $binary?.data?.fileName || 'document.pdf';
const agentId = parseInt(trigger.body?.agent_id, 10) || 0;

const inputData = $json.document.md_content;

// Regex captures inline base64 images from Docling's markdown output. Two
// forms: ![Image](data:...) and bare data: URLs. Unchanged from the
// original, live-verified implementation.
const imgRegex = /!\[Image\]\(data:image\/([^;]+);base64,([A-Za-z0-9+/=\s]+)\)|data:image\/([^;]+);base64,([A-Za-z0-9+/=\s]+)/g;

const tempImages = [];
let match;
while ((match = imgRegex.exec(inputData)) !== null) {
  const mimeType = (match[1] || match[3] || 'unknown').toLowerCase();
  const rawBase64 = match[2] || match[4];
  const cleanBase64 = rawBase64.replace(/\s+/g, '');

  // PNG dimensions from the header (bytes 16-23). JPEG always falls back to
  // 999x999 (no header parsing implemented for it).
  function getPngDimensions(base64) {
    try {
      const binary = atob(base64.substring(0, 40));
      const width  = (binary.charCodeAt(16) << 24) | (binary.charCodeAt(17) << 16) |
                     (binary.charCodeAt(18) << 8)  |  binary.charCodeAt(19);
      const height = (binary.charCodeAt(20) << 24) | (binary.charCodeAt(21) << 16) |
                     (binary.charCodeAt(22) << 8)  |  binary.charCodeAt(23);
      return { width, height };
    } catch(e) { return { width: 999, height: 999 }; }
  }

  const dims = mimeType.includes('png') ? getPngDimensions(cleanBase64) : { width: 999, height: 999 };

  const isKnownUnsupported = ['svg', 'pdf', 'unknown'].some(t => mimeType.includes(t));
  // >= 33 not >= 50: very small images crash some vision models' resize step.
  const isSupported = !isKnownUnsupported && dims.width >= 33 && dims.height >= 33;

  tempImages.push({
    base64: cleanBase64,
    mimeType,
    isSupported,
    index: match.index,
    length: match[0].length,
    width: dims.width,
    height: dims.height
  });
}

let counter = 0;
const cleanMarkdown = inputData.replace(imgRegex, () => {
  counter++;
  return ` ##FIGURE_${counter}## `;
});

// Context before/after each image, for the vision-model prompt (figure
// caption/source is usually right next to the image in the source doc).
const images = tempImages.map((img, i) => {
  const placeholder = ` ##FIGURE_${i + 1}## `;
  const pos = cleanMarkdown.indexOf(placeholder);
  return {
    imageIndex: i + 1,
    base64Image: img.isSupported ? img.base64 : null,
    imageType: img.mimeType,
    isSupported: img.isSupported,
    width: img.width,
    height: img.height,
    totalImages: tempImages.length,
    contextBefore: cleanMarkdown.substring(Math.max(0, pos - 1000), pos).trim(),
    contextAfter: cleanMarkdown.substring(pos + placeholder.length, pos + placeholder.length + 1000).trim()
  };
});

return [{
  json: {
    cleanMarkdown,
    images,
    hasImages: images.some(img => img.isSupported),
    originalFileName,
    agentId,
    fileName: originalFileName.replace(/\.[^/.]+$/, '.md')
  }
}];

// Calls the self-hosted markdowncleaner service (markdowncleaner/ in this
// repo — a thin FastAPI wrapper around the `markdowncleaner` PyPI package,
// MIT, https://github.com/josk0/markdowncleaner). Verified against the
// original deployment's actual running container rather than reconstructed
// from guesswork: same request shape, same option defaults (the original
// n8n workflow only ever sent `markdown`, so it always ran on the wrapper's
// own defaults — replicated here explicitly for clarity). No try/catch: a
// markdowncleaner outage should fail this execution and trigger the error
// email, same as the original workflow's behavior.
const raw = await this.helpers.request({
  method: 'POST',
  url: 'http://smartrag-markdowncleaner:8000/clean',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    markdown: $json.cleanMarkdown || '',
    remove_short_lines: false,
    remove_references: true,
    remove_sections: true,
    fix_encoding: true,
    crimp_linebreaks: true
  }),
  json: false
});
const parsed = JSON.parse(raw);
let cleaned = parsed.cleaned || '';

// Downstream fixes that ran after markdowncleaner in the original workflow
// (self-contained, don't depend on it): an OCR-artifact fix for umlauts
// getting split from the following letter, FIGURE-token spacing
// normalization, and dropping any "## Quellen" (references) section.
cleaned = cleaned.replace(/([äöüÄÖÜß])\s+([a-zA-ZäöüÄÖÜß])/gu, '$1$2');
cleaned = cleaned.replace(/([äöüÄÖÜß])\s+([a-zA-ZäöüÄÖÜß])/gu, '$1$2');
cleaned = cleaned.replace(/([a-zA-ZäöüÄÖÜß])\s+([äöüÄÖÜß])/gu, '$1$2');
cleaned = cleaned.replace(/([a-zA-ZäöüÄÖÜß])\s+([äöüÄÖÜß])/gu, '$1$2');

cleaned = cleaned.replace(/##\s*FIGURE_(\d+)\s*##/g, '##FIGURE_$1##');

const sections = cleaned.split(/(?=^## )/m);
cleaned = sections.filter(s => !s.startsWith('## Quellen')).join('');

return [{
  json: {
    ...$json,
    cleanMarkdown: cleaned.trim()
  }
}];

const images = $json.images || [];
const supportedImages = images.filter(img => img.isSupported && img.base64Image);

if (supportedImages.length === 0) {
  return [{ json: { skip: true } }];
}

return supportedImages.map(img => ({
  json: {
    ...img,
    cleanMarkdown: $json.cleanMarkdown,
    fileName: $json.fileName,
    originalFileName: $json.originalFileName,
    agentId: $json.agentId
  }
}));

// Provider-agnostic image description — replaces a hardcoded call to a
// specific Ollama instance's IP with the same LLM_PROVIDER already
// configured for the course's agents ($env.LLM_PROVIDER/LLM_API_KEY/
// LLM_BASE_URL/LLM_MODEL_STRONG), matching content-admin/llm_client.py's
// already-verified per-provider request shapes (same endpoints/headers/
// auth), extended with an image content block. Uses this.helpers.request
// like every other outbound call already in this workflow's Code nodes —
// no need for the old raw-socket keepAlive workaround, which existed
// specifically to survive Ollama's long idle think time; hosted APIs
// respond in seconds.
//
// Image content-block formats verified directly against each provider's
// docs: Anthropic (content: [{type:'image', source:{type:'base64', ...}}]),
// OpenAI (content: [{type:'image_url', image_url:{url:'data:...'}}]), Google
// (parts: [{inline_data:{mime_type, data}}]). Mistral/OpenRouter/"custom"
// reuse the OpenAI image_url shape as a disclosed assumption — they're
// already OpenAI-Chat-Completions-compatible endpoints for text (verified
// in llm_client.py), not independently confirmed for images. Cohere has no
// verified image format here and is explicitly unsupported rather than
// guessed.
const item = $input.first().json;
// No fallback. Substituting a different provider than the one
// configured sends the request to the wrong vendor with the wrong
// credential shape, and the reply is an auth error from a service
// nobody meant to call — which points away from the real problem,
// an empty variable.
const provider = ($env.LLM_PROVIDER || '').trim();
if (!provider) {
  return [{ json: { message: { content: '[Image description skipped: LLM_PROVIDER is empty in .env]' } } }];
}
const apiKey   = $env.LLM_API_KEY  || '';
const model    = $env.LLM_MODEL_STRONG || '';
const baseUrl  = $env.LLM_BASE_URL || '';
const language = ($('Upload Webhook').first().json.body?.language) || 'en';

const mimeType = `image/${item.imageType === 'jpg' ? 'jpeg' : item.imageType}`;

const systemPrompt =
  'You are a specialist in describing figures/diagrams from academic and ' +
  'course material for a retrieval-augmented generation (RAG) system. Your ' +
  'description must let a language model that never sees the original image ' +
  'answer questions about it correctly from your text alone.\n\n' +
  'Rules: no pronouns ("this", "that", "here") — always use the full term; ' +
  'state causal relationships explicitly ("X leads to Y, which means Z"); ' +
  'name any color-coding and what it means; describe symbols/icons even ' +
  'without visible text; if the figure has multiple sub-panels (a, b, c, ' +
  'd...), describe each separately and label it; note ambiguity as such ' +
  'instead of guessing. Respond in ' + language + '.';

const userPrompt =
  'Describe the attached figure.\n\n' +
  '=== DOCUMENT CONTEXT ===\n\n' +
  'Text BEFORE the figure:\n' + (item.contextBefore || 'none — possibly a title page or cover') + '\n\n' +
  'Text AFTER the figure:\n' + (item.contextAfter || 'not available') + '\n\n' +
  '=== OUTPUT FORMAT (follow exactly) ===\n\n' +
  '**[Figure number/title from context, if identifiable]**\n' +
  'Source: [author, year, from context — "not stated" if not identifiable]\n\n' +
  '**Figure type:** [e.g. cyclical process model, flowchart, set diagram, ' +
  'icon row, comparison layout, bar/line/scatter chart, photo, ' +
  'screenshot/UI, diagram]\n\n' +
  '**Key message:** [4-7 sentences: what concept or model does this figure ' +
  'convey, on the meta level?]\n\n' +
  '**Description:** [full description following the rules above]\n\n' +
  '**Keywords:** [term1 | term2 | term3 | ...]\n\n' +
  'Return only the formatted description, no meta-commentary.';

let url, headers, body, extractText;

if (provider === 'anthropic') {
  url = 'https://api.anthropic.com/v1/messages';
  headers = { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' };
  body = {
    model,
    max_tokens: 2048,
    system: systemPrompt,
    messages: [{
      role: 'user',
      content: [
        { type: 'image', source: { type: 'base64', media_type: mimeType, data: item.base64Image } },
        { type: 'text', text: userPrompt }
      ]
    }]
  };
  extractText = (data) => (data.content || []).find(b => b.type === 'text')?.text || '';
} else if (provider === 'google') {
  url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
  headers = { 'x-goog-api-key': apiKey, 'Content-Type': 'application/json' };
  body = {
    systemInstruction: { parts: [{ text: systemPrompt }] },
    contents: [{
      role: 'user',
      parts: [
        { inline_data: { mime_type: mimeType, data: item.base64Image } },
        { text: userPrompt }
      ]
    }],
    generationConfig: { maxOutputTokens: 2048 }
  };
  extractText = (data) => data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
} else if (provider === 'cohere') {
  return [{ json: { message: { content: '[Image description skipped: Cohere image format not implemented — see ingest-document.json comments]' } } }];
} else {
  // openai / mistral / openrouter / custom — OpenAI-compatible Chat
  // Completions endpoint, image_url content block (disclosed assumption
  // for mistral/openrouter/custom, see comment above).
  if (provider === 'openai') url = 'https://api.openai.com/v1/chat/completions';
  else if (provider === 'mistral') url = 'https://api.mistral.ai/v1/chat/completions';
  else if (provider === 'openrouter') url = 'https://openrouter.ai/api/v1/chat/completions';
  else url = `${(baseUrl || '').replace(/\/$/, '')}/chat/completions`;

  headers = { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' };
  body = {
    model,
    messages: [
      { role: 'system', content: systemPrompt },
      {
        role: 'user',
        content: [
          { type: 'image_url', image_url: { url: `data:${mimeType};base64,${item.base64Image}` } },
          { type: 'text', text: userPrompt }
        ]
      }
    ]
  };
  if (provider === 'openai') body.max_completion_tokens = 2048;
  else body.max_tokens = 2048;
  extractText = (data) => data?.choices?.[0]?.message?.content || '';
}

try {
  const raw = await this.helpers.request({
    method: 'POST',
    url,
    headers,
    body: JSON.stringify(body),
    json: false
  });
  const parsed = JSON.parse(raw);
  const text = extractText(parsed);
  return [{ json: { message: { content: text || '[No description returned]' } } }];
} catch (e) {
  return [{ json: { message: { content: `[Image description failed: ${e.message}]` } } }];
}

const imageIndex = $('Prepare Image Loop').item.json.imageIndex;
const raw = $json.message?.content || '';

const content = raw.includes('</think>')
  ? raw.split('</think>').pop().trim()
  : raw.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

return [{
  json: {
    imageIndex: imageIndex,
    message: { content }
  }
}];

const allAnalyses = $input.all();
const meta = $('Clean Markdown').first().json;
let finalDocument = meta.cleanMarkdown || '';

const analysesWithIndex = allAnalyses
  .map(item => ({
    imageIndex: item.json.imageIndex,
    content: item.json.message?.content ?? ''
  }))
  .filter(a => Number.isInteger(a.imageIndex) && a.content.trim().length > 0)
  .sort((a, b) => a.imageIndex - b.imageIndex);

const analysisMap = {};
for (const a of analysesWithIndex) {
  analysisMap[a.imageIndex] = a.content;
}

finalDocument = finalDocument.replace(/##\s*FIGURE_(\d+)\s*##/g, '##FIGURE_$1##');
const parts = finalDocument.split(/##FIGURE_(\d+)##/);

finalDocument = '';
for (let i = 0; i < parts.length; i++) {
  if (i % 2 === 0) {
    finalDocument += parts[i];
  } else {
    const index = parseInt(parts[i]);
    const analysis = analysisMap[index];
    if (analysis) {
      finalDocument += `\n---\n> ### Figure ${index} — AI description\n>\n${analysis.split('\n').map(line => '> ' + line).join('\n')}\n---\n`;
    } else {
      finalDocument += `[No description for figure ${index}]`;
    }
  }
}

return [{
  json: {
    ...meta,
    message: { content: finalDocument }
  }
}];

const replaceUmlauts = (str) => {
  if (!str) return str;
  return str
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
    .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue')
    .replace(/ß/g, 'ss')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
};

const toS3Safe = (str) => replaceUmlauts(str).replace(/[^a-zA-Z0-9/_-]/g, '-').toLowerCase();

const rawFileName = $json.originalFileName || 'document';
const agentId = $json.agentId || 0;
const cleanedContent = $json.message?.content || '';

return [{
  json: {
    message: { content: cleanedContent },
    directory: `agent_${agentId}`,
    agentId,
    originalFileName: toS3Safe(rawFileName.replace(/\.[^/.]+$/, '')) + '.md'
  }
}];

// Type detection stays regex-only (no LLM call) — figure caption blocks are
// stripped first so they don't confuse the interview/numbered-heading checks.
const content = $json.message?.content || '';

const isInterview = /###\s+.+[\s\S]*?<!--\s*ts:/.test(content);
const isNumberedHeadings = /^##\s+\d+\.\d+[.\s]/m.test(content);

const docType = isInterview ? 'interview'
  : isNumberedHeadings ? 'wissensbausteine'
  : 'document';

return [{ json: { ...$json, doc_type: docType } }];

// Metadata comes directly from the upload form (content-admin GUI, itself
// optionally AI-assisted via /slot/<n>/optimize-style suggestion — see the
// batch plan) — no LLM round-trip inside this workflow at all anymore, and
// no hardcoded per-course author/year defaults like the old version had.
const trigger = $('Upload Webhook').first().json.body || {};
const d = $json;
const content = d.message?.content || '';

const title    = trigger.title    || d.originalFileName.replace(/\.md$/, '');
const authors  = trigger.authors  || '';
const year     = trigger.year     ? parseInt(trigger.year, 10) : null;
const topic    = trigger.topic    || '';
const language = trigger.language || 'en';

const frontmatter = [
  '---',
  `title: "${title.replace(/"/g, "'")}"`,
  `authors: "${authors.replace(/"/g, "'")}"`,
  `year: ${year ?? 'null'}`,
  `type: ${d.doc_type || 'document'}`,
  `topic: "${topic.replace(/"/g, "'")}"`,
  `language: ${language}`,
  '---',
  ''
].join('\n');

return [{
  json: {
    ...d,
    message: { content: frontmatter + content },
    bodyContent: content,
    meta: {
      title, authors, year, topic, language,
      doc_type: d.doc_type || 'document',
      agent_id: d.agentId,
      block_number: d.agentId,
      source_file: `${d.directory}/${d.originalFileName}`,
      bucket: `${$env.COURSE_ID || 'smartrag'}-rag`
    }
  }
}];

// The S3 node's own output is its upload API response (ETag/Location/...),
// not the document data — rebuild the {bodyContent, metadata} shape the
// "Chunk + Embed" sub-workflow's trigger expects from what "Build
// Frontmatter" produced, referenced back explicitly since it's no longer
// the current item.
const built = $('Build Frontmatter').first().json;

return [{
  json: {
    bodyContent: built.bodyContent,
    metadata: built.meta
  }
}];
